.ai-panel { width: 100%; }.ai-controls { display: grid; gap: 12px; margin-top: 20px; }.ai-controls textarea { min-height: 150px; resize: vertical; font-family: ui-monospace, SFMono-Regular, Consolas, monospace; }.ai-response { margin-top: 20px; line-height: 1.7; background: #0d1117; color: #c9d1d9; border: 1px solid #30363d; border-radius: 10px; padding: 24px; }

.ai-answer-view { display: grid; gap: 14px; padding: 20px; border: 1px solid #30363d; border-radius: 12px; background: #0d1117; }
.ai-answer-confidence { justify-self: start; padding: 4px 10px; border-radius: 99px; color: #7ee787; border: 1px solid #2ea043; background: rgba(46,160,67,.12); font-size: 10px; font-weight: 800; letter-spacing: .04em; }
.ai-answer-flag { margin: 0; padding: 8px 12px; border-radius: 8px; color: #ffab70; border: 1px solid #9a6700; background: rgba(187,128,9,.12); font-size: 12px; font-weight: 700; }
.ai-answer-lede { margin: 0; color: #f0f6fc; font: 700 17px/1.5 "Space Grotesk"; }
.ai-answer-points { display: grid; gap: 10px; margin: 0; padding: 0; list-style: none; }
.ai-answer-points li { display: grid; grid-template-columns: 14px 1fr; gap: 10px; align-items: start; color: #c9d1d9; line-height: 1.65; }
.ai-answer-points li i { width: 7px; height: 7px; margin-top: 7px; border-radius: 50%; background: #58a6ff; }
.ai-answer-metric { padding: 1px 5px; border-radius: 4px; color: #7ee787; background: rgba(46,160,67,.16); font-weight: 800; font-style: normal; }
.ai-answer-actions { display: grid; gap: 8px; margin-top: 4px; }
.ai-answer-action-card { padding: 12px 14px; border-radius: 9px; border: 1px solid #30363d; border-left-width: 3px; background: #161b22; }
.ai-answer-action-card header { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.ai-answer-action-card strong { color: #f0f6fc; font-size: 12px; }
.ai-answer-action-card p { margin: 5px 0 0; color: #8b949e; font-size: 12px; line-height: 1.55; }
.ai-answer-action-card b { padding: 2px 7px; border-radius: 99px; font-size: 8px; font-weight: 900; letter-spacing: .04em; }
.ai-answer-action-card.risk-low { border-left-color: #2ea043; }
.ai-answer-action-card.risk-low b { color: #7ee787; background: rgba(46,160,67,.16); }
.ai-answer-action-card.risk-medium { border-left-color: #bb8009; }
.ai-answer-action-card.risk-medium b { color: #f2cc60; background: rgba(187,128,9,.16); }
.ai-answer-action-card.risk-high, .ai-answer-action-card.risk-critical { border-left-color: #da3633; }
.ai-answer-action-card.risk-high b, .ai-answer-action-card.risk-critical b { color: #ff7b72; background: rgba(218,54,51,.16); }
.ai-answer-evidence { display: flex; flex-wrap: wrap; gap: 8px; }
.ai-answer-evidence span { display: flex; align-items: center; gap: 6px; padding: 5px 9px; border-radius: 7px; color: #8b949e; border: 1px solid #30363d; background: #161b22; font-size: 9px; font-weight: 800; text-transform: uppercase; letter-spacing: .03em; }
.ai-answer-evidence code { color: #58a6ff; font-size: 9px; text-transform: none; letter-spacing: 0; }
.ai-answer-warnings { display: grid; gap: 6px; }
.ai-answer-warnings span { padding: 8px 12px; border-radius: 8px; color: #ffab70; border: 1px solid #9a6700; background: rgba(187,128,9,.1); font-size: 11px; }

.ai-history-layout { display: grid; grid-template-columns: minmax(260px,.34fr) 1fr; gap: 14px; align-items: start; }
.ai-history-conversations { display: grid; gap: 6px; max-height: 620px; overflow: auto; padding: 8px; }
