.ai-history-conversation-row time { color: var(--muted); font-size: 9px; }
.ai-history-filter { margin: 0 8px 10px; padding: 9px 12px; border: 1px solid var(--ai-line); border-radius: 8px; font-size: 12px; width: calc(100% - 16px); }
.ai-history-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 14px; overflow-y: auto; padding: 2px 4px 8px 2px; flex: 1; align-content: start; }
.ai-history-card { display: grid; gap: 6px; padding: 16px 18px; border: 1px solid var(--line); border-radius: 12px; background: #fff; text-align: left; cursor: pointer; transition: border-color .15s, box-shadow .15s, transform .15s; }
.ai-history-card:hover { border-color: var(--ai-mint); box-shadow: 0 8px 22px rgba(0,0,0,.07); transform: translateY(-2px); }
.ai-history-card.active { border-color: var(--ai-mint); box-shadow: 0 0 0 1px var(--ai-mint); }
.ai-history-card strong { font-size: 13px; line-height: 1.4; }
.ai-history-card small { color: var(--muted); font-size: 9.5px; text-transform: uppercase; letter-spacing: .03em; }
.ai-history-card time { color: var(--muted); font-size: 9.5px; }
.ai-history-reader { padding: 22px 24px; min-height: 300px; }
.ai-history-doc header { padding-bottom: 16px; border-bottom: 1px solid var(--ai-line); margin-bottom: 20px; }
.ai-history-doc h2 { margin: 4px 0; font: 700 clamp(20px,2.2vw,30px) "Space Grotesk"; letter-spacing: -.03em; }
.ai-history-doc > header small { color: var(--muted); font-size: 11px; }
.ai-history-messages { display: grid; gap: 22px; }
.ai-history-message-meta { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
.ai-history-message-meta b { font-size: 10px; text-transform: uppercase; letter-spacing: .04em; color: #087b55; }
.ai-history-message-meta time { color: var(--muted); font-size: 10px; }
.ai-history-message-meta span { padding: 2px 7px; border-radius: 99px; background: #f6f8fa; color: var(--muted); font-size: 8px; font-weight: 800; }
.ai-history-question { padding: 12px 16px; border-radius: 10px; background: #f6f8fa; font-size: 13px; font-weight: 600; line-height: 1.55; }
@media (max-width: 1050px) { .ai-history-layout { grid-template-columns: 1fr; } }
.ai-setup { display: grid; gap: 12px; margin-top: 22px; padding: 22px; background: #f6f8fa; border: 1px solid #d0d7de; border-radius: 10px; }.ai-setup label { margin: 0; }.ai-privacy-note { padding:9px 11px;color:#765900;border:1px solid #e4cf81;border-radius:7px;background:#fff8d9;font-size:10px;line-height:1.5 }.secret-heading, .ai-connection { display: flex; justify-content: space-between; align-items: center; gap: 16px; }.secret-heading > div { display: flex; flex-direction: column; }.secret-heading span { color: var(--muted); font-size: 12px; margin-top: 4px; }.security-chip { display: inline-flex; background: #dafbe1; color: #116329 !important; border: 1px solid #aceebb; padding: 5px 8px; border-radius: 99px; font-weight: 800; white-space: nowrap; }.ai-connection { padding: 12px 14px; border: 1px solid #aceebb; background: #dafbe1; border-radius: 8px; color: #116329; font-size: 12px; }.ai-connection > div { display: flex; gap: 8px; }.text-button.inline { width: auto; margin: 0; padding: 3px 6px; font-size: 11px; }.text-button.danger { color: var(--red); }

@media (max-width: 1150px) { .kpi-grid { grid-template-columns: 1fr 1fr; }.upload-strip, .access-strip { grid-template-columns: 1fr; }.analytics-grid { grid-template-columns: 1fr; }.analytics-grid .wide { grid-column: auto; }.scorecard { grid-template-columns: 1fr 1fr; }.active-users { min-width: auto; }.active-users > div:last-child { display: none; } }
@media (max-width: 760px) { .login-shell { grid-template-columns: 1fr; }.login-story { min-height: 46vh; padding: 42px 28px; }.login-story h1 { font-size: 44px; }.story-grid { gap: 20px; }.login-panel { padding: 24px; }.product-shell { display: block; }.sidebar { position: static; width: 100%; min-height: auto; }.sidebar nav { grid-template-columns: repeat(4, 1fr); }.sidebar nav button { text-align: center; padding: 9px 3px; font-size: 11px; }.sidebar-bottom { margin-top: 22px; }.workspace { padding: 24px 14px 50px; }.topbar { align-items: stretch; flex-direction: column; }.topbar-actions { flex-direction: column; }.topbar-actions select { min-width: 0; }.kpi-grid { grid-template-columns: 1fr 1fr; }.panel { padding: 16px; }.scorecard { grid-template-columns: 1fr 1fr; } }
@media (max-width: 760px) { .access-form { grid-template-columns: 1fr; } }
@media (max-width: 760px) { .workspace-access-head { flex-direction: column; }.workspace-invite { grid-template-columns: 1fr; }.workspace-member-list article { grid-template-columns: 42px 1fr auto; }.workspace-member-list .revoke-button { grid-column: 2; justify-self: start; } }

.home-grid { display: grid; grid-template-columns: 1.35fr .65fr; gap: 16px; }
.home-grid .panel { margin-top: 0; }
.home-hero, .repository-launchpad { grid-column: 1 / -1; }
.home-hero { position: relative; overflow: hidden; background: radial-gradient(circle at 96% 12%, rgba(9,105,218,.14), transparent 32%), linear-gradient(135deg, #fff, #f6f8fa); }
.home-hero::after { content: "GW"; position: absolute; right: 30px; top: -27px; color: rgba(13,17,23,.035); font: 800 150px "Space Grotesk"; letter-spacing: -.1em; pointer-events: none; }
.category-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 22px; position: relative; z-index: 1; }
.category-grid .category-card { display: flex; flex-direction: column; align-items: flex-start; min-height: 120px; padding: 15px; border: 1px solid var(--line); border-radius: 10px; background: rgba(255,255,255,.86); box-shadow: 0 1px 0 rgba(31,35,40,.04); text-align: left; cursor: pointer; transition: .15s ease; }
.category-grid .category-card:hover { border-color: #0969da; transform: translateY(-1px); box-shadow: 0 8px 20px rgba(9,105,218,.1); }
.category-grid .category-card.active { border-color: #0969da; background: #ddf4ff; box-shadow: 0 0 0 2px rgba(9,105,218,.25); }
.category-grid .category-card::before { content: ""; width: 34px; height: 25px; margin-bottom: 18px; border: 2px solid #0969da; border-radius: 4px; background: linear-gradient(155deg,#ddf4ff 55%,#b6e3ff 56%); box-shadow: 8px -5px 0 -4px #0969da; }
.category-grid strong { font: 700 15px "Space Grotesk"; }.category-grid small { color: var(--muted); font-size: 10px; margin-top: 5px; }.category-path { color: #0969da; font-size: 8px; letter-spacing: .15em; font-weight: 900; margin-bottom: 6px; }

/* Pulse filter — a scannable activity-heat timeline, not a dropdown. */
.signal-filter { grid-column: 1 / -1; position: relative; overflow: hidden; color: #f0f6fc; border: 1px solid #30363d; border-radius: 16px; background: radial-gradient(circle at 88% 10%,rgba(9,105,218,.28),transparent 30%),radial-gradient(circle at 8% 100%,rgba(46,160,67,.22),transparent 36%),linear-gradient(135deg,#0d1117 0%,#111b22 60%,#0d2b20 100%); box-shadow: 0 22px 55px rgba(13,17,23,.18); }
.signal-filter::after { content: "GW"; position: absolute; right: 22px; top: -34px; color: rgba(240,246,252,.05); font: 800 150px "Space Grotesk"; letter-spacing: -.1em; pointer-events: none; }
.signal-filter .eyebrow { color: #58a6ff; }
.signal-filter h2 { color: #fff; }
.signal-filter .panel-header, .signal-filter .signal-rail-wrap, .signal-filter .signal-receivers { position: relative; z-index: 1; }
.signal-clear { flex-shrink: 0; padding: 8px 14px; border: 1px solid #3fb950; border-radius: 99px; color: #7ee787; background: rgba(63,185,80,.12); font-size: 10px; font-weight: 800; white-space: nowrap; }
.signal-clear:hover { background: rgba(63,185,80,.22); }
.signal-rail-wrap { margin-top: 20px; }
.signal-beats { display: flex; gap: 6px; padding-bottom: 4px; overflow-x: auto; }
.signal-beat { position: relative; display: flex; flex: 0 0 52px; flex-direction: column; align-items: center; gap: 6px; padding: 10px 4px 14px; border: 1px solid #30363d; border-radius: 10px; background: rgba(255,255,255,.04); color: #9da7b3; transition: .15s ease; }
.signal-beat:hover { border-color: #58a6ff; background: rgba(88,166,255,.1); }
.signal-beat i { display: block; width: 10px; height: calc(6px + var(--intensity, 0) * 38px); border-radius: 4px; background: linear-gradient(180deg,#58a6ff,#3fb950); box-shadow: 0 0 10px rgba(88,166,255,.35); }
.signal-beat span { font-size: 10px; font-weight: 800; color: #f0f6fc; }
.signal-beat small { font-size: 8px; color: #6e7781; }
.signal-beat.active { border-color: #58a6ff; background: rgba(88,166,255,.18); box-shadow: 0 0 0 2px rgba(88,166,255,.3); }
.signal-beat.active i { box-shadow: 0 0 16px rgba(88,166,255,.7); }
.signal-pins { position: absolute; bottom: 4px; left: 0; right: 0; display: flex; justify-content: center; gap: 3px; }
.signal-pins b { width: 6px; height: 6px; border-radius: 50%; background: var(--pin-color, #58a6ff); box-shadow: 0 0 5px var(--pin-color, #58a6ff); }
.signal-receivers { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-top: 18px; padding-top: 16px; border-top: 1px solid rgba(255,255,255,.08); }
.signal-link-toggle { display: flex; align-items: center; gap: 6px; flex-shrink: 0; padding: 6px 12px; border: 1px solid #30363d; border-radius: 99px; color: #9da7b3; background: rgba(255,255,255,.04); font-size: 9px; font-weight: 800; text-transform: uppercase; letter-spacing: .04em; }
.signal-link-toggle i { width: 7px; height: 7px; border-radius: 50%; background: #484f58; }
.signal-link-toggle.linked { color: #58a6ff; border-color: #58a6ff; background: rgba(88,166,255,.12); }
.signal-link-toggle.linked i { background: #58a6ff; box-shadow: 0 0 6px rgba(88,166,255,.6); }
.signal-link-toggle:hover { border-color: #58a6ff; }
.signal-domain-chip { padding: 5px 10px; border: 1px solid #d29922; border-radius: 99px; color: #e3b341; background: rgba(210,153,34,.14); font-size: 9px; font-weight: 800; }
.signal-receiver-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-left: auto; }
.signal-receiver-chip { display: flex; align-items: center; gap: 6px; padding: 5px 10px; border: 1px solid #30363d; border-radius: 99px; color: #9da7b3; background: rgba(255,255,255,.04); font-size: 9px; font-weight: 700; }
.signal-receiver-chip:disabled { cursor: default; }
.signal-receiver-chip i { width: 6px; height: 6px; border-radius: 50%; background: #484f58; }
.signal-receiver-chip small { color: var(--pin-color, #7ee787); font-weight: 800; }
.signal-receiver-chip.live { color: var(--pin-color, #7ee787); border-color: var(--pin-color, #3fb950); background: rgba(255,255,255,.06); }
.signal-receiver-chip.live i { background: var(--pin-color, #3fb950); box-shadow: 0 0 6px var(--pin-color, rgba(63,185,80,.7)); animation: signalPulse 1.6s ease-in-out infinite; }
.signal-receiver-chip.armed { box-shadow: 0 0 0 2px var(--pin-color, #58a6ff); }
.signal-receiver-chip b { color: #f0f6fc; }
@keyframes signalPulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }

/* Tuned-dot — a small synced indicator on any panel that's currently
   listening to a SignalFilter's selection, so the connection between the
   filter and its receivers reads as live, matched state rather than prose. */
.tuned-dot { display: inline-block; width: 7px; height: 7px; margin-left: 8px; border-radius: 50%; background: #d0d7de; vertical-align: middle; }
.tuned-dot.live { background: var(--pin-color, #3fb950); box-shadow: 0 0 6px var(--pin-color, rgba(63,185,80,.6)); animation: signalPulse 1.6s ease-in-out infinite; }
.repository-launchpad-controls { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.access-toggle { display: flex; align-items: center; gap: 7px; padding: 7px 12px; border: 1px solid var(--line); border-radius: 99px; color: var(--muted); background: #fff; font-size: 10px; font-weight: 800; white-space: nowrap; }
.access-toggle i { width: 8px; height: 8px; border-radius: 50%; background: #d0d7de; }
.access-toggle:hover { border-color: #0969da; }
.access-toggle.active { color: #0969da; border-color: #0969da; background: #ddf4ff; }
.access-toggle.active i { background: #0969da; box-shadow: 0 0 0 3px rgba(9,105,218,.15); }
.repository-card-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.repository-card-grid > button { display: grid; grid-template-columns: 42px 1fr auto; gap: 12px; align-items: center; text-align: left; border: 1px solid var(--line); border-radius: 9px; padding: 14px; background: #fff; color: var(--ink); transition: .18s ease; }
.repository-card-grid > button:hover { border-color: #0969da; background: #f6faff; transform: translateY(-1px); box-shadow: 0 8px 24px rgba(9,105,218,.09); }
.repository-card-grid > button.repository-locked { cursor: not-allowed; opacity: .72; background: repeating-linear-gradient(135deg,#f6f8fa,#f6f8fa 8px,#eef1f4 8px,#eef1f4 16px); }
.repository-card-grid > button.repository-locked:hover { border-color: var(--line); transform: none; box-shadow: none; }
.access-badge { padding: 5px 8px; border-radius: 99px; text-transform: uppercase; letter-spacing: .04em; }
.access-owner,.access-editor { color:#116329!important;background:#dafbe1 }.access-viewer { color:#0550ae!important;background:#ddf4ff }.access-denied { color:#57606a!important;background:#eaeef2 }
.repo-icon { width: 40px; height: 46px; display: grid; place-items: center; border-radius: 6px 10px 6px 6px; background: #1f883d; color: white; font-weight: 900; font-size: 11px; clip-path: polygon(0 0, 75% 0, 100% 22%, 100% 100%, 0 100%); }
.repository-card-grid span:nth-child(2) { display: flex; flex-direction: column; min-width: 0; }.repository-card-grid strong { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }.repository-card-grid small { color: var(--muted); margin-top: 4px; }.repository-card-grid b { color: #0969da; font-size: 9px; white-space: nowrap; }
.working-copy-list, .recent-activity { display: grid; gap: 8px; }
