.ai-progress-track { height: 10px; border-radius: 99px; background: #e8edf1; overflow: hidden; }
.ai-progress-fill { height: 100%; border-radius: 99px; transition: width .5s ease-out; }
.ai-progress-fill.rainbow {
  background: linear-gradient(90deg, #ff5f6d, #ffc371, #f9f871, #6fde8f, #4fc3f7, #8a7bff, #ff5f6d);
  background-size: 300% 100%;
  animation: ai-progress-shimmer 2.2s linear infinite;
}
@keyframes ai-progress-shimmer { 0% { background-position: 0% 50%; } 100% { background-position: 300% 50%; } }
.ai-progress-label { color: var(--muted); font-size: 11px; font-weight: 700; font-variant-numeric: tabular-nums; }

/* Data Insights -- ask panel (inside AI Command Center's light-themed controls room) */
.data-insights-panel { padding: 18px 22px; border-bottom: 1px solid #dae3df; background: linear-gradient(160deg, #fff 0%, #f5f9f7 100%); }
.data-insights-panel .panel-header { padding: 0 0 12px; }
.data-insights-panel .panel-header h3 { margin: 4px 0 6px; font: 700 22px "Space Grotesk"; }
.data-insights-panel .panel-header p.muted { max-width: 640px; color: #66786f; font-size: 11px; line-height: 1.6; }
.insight-prompt-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.insight-prompt-chip { padding: 8px 13px; border: 1px solid #c2d2cb; border-radius: 99px; background: #fff; color: #0d6648; font-size: 10.5px; font-weight: 800; cursor: pointer; transition: border-color .15s, background .15s; }
.insight-prompt-chip:hover:not(:disabled) { border-color: #3fb950; background: #effbf5; }
.insight-prompt-chip:disabled { opacity: .5; cursor: default; }
.insight-ask-bar { display: grid; grid-template-columns: 1fr auto; gap: 10px; align-items: end; }
.insight-ask-bar textarea { min-height: 56px; padding: 12px 14px; border: 1px solid #c2d2cb; border-radius: 10px; font-size: 12.5px; line-height: 1.5; resize: vertical; }
.insight-ask-bar .primary-button { padding: 12px 20px; border: 1px solid #51cb9b; border-radius: 10px; color: #062d1f; background: var(--ai-mint); font-weight: 900; white-space: nowrap; }
.insight-ask-bar .primary-button:disabled { opacity: .5; cursor: default; }
.insight-run-progress { margin-top: 14px; }

/* Data Insights -- full-screen report modal */
.insights-report-dialog .panel-header { align-items: flex-start; padding-right: 90px; }
.insights-report-dialog .panel-header h2 { font-size: clamp(22px, 2.4vw, 30px); line-height: 1.25; }
.insight-confidence-badge { flex-shrink: 0; padding: 10px 16px; border-radius: 12px; background: conic-gradient(#3fb950 calc(var(--confidence) * 1%), #e8edf1 0); text-align: center; }
.insight-confidence-badge span { display: block; padding: 8px 10px; border-radius: 8px; background: #fff; color: #116329; font-size: 10.5px; font-weight: 900; }
.insight-view-toggle { display: inline-flex; gap: 4px; margin: 14px 0 6px; padding: 4px; border-radius: 99px; background: #f0f3f2; width: max-content; }
.insight-view-toggle button { padding: 7px 16px; border: 0; border-radius: 99px; background: transparent; color: #57606a; font-size: 11px; font-weight: 800; cursor: pointer; }
.insight-view-toggle button.active { background: #fff; color: #116329; box-shadow: 0 1px 3px rgba(0,0,0,.12); }
.insight-report-body { padding: 12px 4px; }
.insight-table-wrap { max-height: 360px; overflow: auto; border: 1px solid var(--line); border-radius: 10px; }
.insight-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.insight-table th { position: sticky; top: 0; padding: 10px 14px; text-align: left; color: #57606a; background: #f6f8fa; font-size: 9.5px; font-weight: 900; text-transform: uppercase; letter-spacing: .03em; border-bottom: 1px solid var(--line); }
.insight-table td { padding: 9px 14px; border-bottom: 1px solid #eef1f3; }
.insight-forecast-callout { display: flex; align-items: center; gap: 14px; margin: 16px 0; padding: 14px 18px; border: 1px solid #c2d2cb; border-radius: 12px; background: #f5f9f7; }
.insight-forecast-arrow { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; background: #fff; font-size: 20px; font-weight: 900; }
.insight-forecast-arrow.direction-up { color: #116329; }
.insight-forecast-arrow.direction-down { color: #a40e26; }
.insight-forecast-arrow.direction-flat { color: #57606a; }
.insight-explainability { margin: 18px 0; }
.insight-key-terms { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 10px; }
.insight-key-term { padding: 5px 10px; border-radius: 99px; background: #eaf2fd; color: #0969da; font-size: 10px; font-weight: 800; }
/* The bullet/action/warning classes below are shared with AIAnswerView's dark Copilot answer pane -- overridden here for this light-themed modal. */
.insights-report-dialog .ai-answer-points li { color: #24292f; }
.insights-report-dialog .ai-answer-points li i { background: #3fb950; }
.insights-report-dialog .ai-answer-metric { padding: 1px 5px; border-radius: 4px; background: #dafbe1; color: #116329; font-weight: 800; }
.insights-report-dialog .ai-answer-actions { display: grid; gap: 10px; margin-top: 14px; }
.insights-report-dialog .ai-answer-action-card { background: #fff; border-color: var(--line); border-left-width: 3px; border-left-color: #0969da; }
.insights-report-dialog .ai-answer-action-card strong { color: var(--ink); }
.insights-report-dialog .ai-answer-action-card p { color: #57606a; }
.insights-report-dialog .ai-answer-warnings span { color: #865f00; background: #fff8d9; border-color: #e4cf81; }
.working-copies-date-filter { display: flex; align-items: center; gap: 10px; margin: 12px 0 14px; flex-shrink: 0; flex-wrap: wrap; }
.working-copies-date-filter label { display: flex; align-items: center; gap: 8px; margin: 0; color: var(--muted); font-size: 11.5px; font-weight: 700; }
.working-copies-date-filter input[type="date"] { padding: 8px 10px; border: 1px solid var(--line); border-radius: 8px; font-size: 12px; }
.working-copies-date-filter button { padding: 8px 12px; border: 1px solid var(--line); border-radius: 8px; background: #fff; color: var(--muted); font-size: 11px; font-weight: 700; cursor: pointer; }
.working-copies-date-filter button:hover { border-color: #cf222e; color: #cf222e; }
