.working-copy-last-seen { flex-shrink: 0; color: var(--muted); font-size: 9.5px; }
.working-copies-pagination { display: flex; align-items: center; justify-content: center; gap: 16px; margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--line); flex-shrink: 0; }
.working-copies-pagination-label { color: var(--muted); font-size: 11.5px; font-variant-numeric: tabular-nums; }
