.stage4-insights { display: grid; gap: 16px; }
.stage4-insights .panel { margin: 0; }
.insight-hero { display: grid; grid-template-columns: 1fr auto; gap: 28px; align-items: center; min-height: 220px; padding: 32px; overflow: hidden; color: #f0f6fc; border: 1px solid #30363d; border-radius: 14px; background: radial-gradient(circle at 78% -30%,rgba(9,105,218,.6),transparent 48%),linear-gradient(125deg,#0d1117,#161b22); box-shadow: 0 25px 60px rgba(13,17,23,.2); }
.insight-hero::after { content:"GW";position:absolute;right:20px;top:-34px;color:rgba(240,246,252,.05);font:800 150px "Space Grotesk";letter-spacing:-.1em;pointer-events:none }.insight-hero > * { position:relative;z-index:1 }.insight-hero .eyebrow { color:#58a6ff }.insight-hero h2 { margin:0;font:700 clamp(38px,5vw,68px) "Space Grotesk";letter-spacing:-.05em }.insight-hero p:last-child { max-width:700px;color:#8b949e;line-height:1.65 }
.pulse-score { min-width: 210px; aspect-ratio: 1; display:grid;place-content:center;text-align:center;border:1px solid #238636;border-radius:50%;background:radial-gradient(circle,rgba(46,160,67,.18),transparent 68%);box-shadow:0 0 0 20px rgba(46,160,67,.035),0 0 0 40px rgba(46,160,67,.02) }.pulse-score span,.pulse-score small { color:#8b949e;font-size:9px;text-transform:uppercase }.pulse-score strong { margin:4px 0;color:#7ee787;font:700 42px "Space Grotesk" }
.insight-domain-grid { display:grid;grid-template-columns:repeat(5,1fr);gap:16px }.insight-domain { position:relative;overflow:hidden }.insight-domain::before { content:"";position:absolute;inset:0 auto 0 0;width:4px;background:var(--domain) }.insight-domain.version { --domain:#0969da }.insight-domain.workflow { --domain:#8250df }.insight-domain.quality { --domain:#1f883d }.insight-domain.ai-domain { --domain:#1b7c83 }.insight-domain.macros { --domain:#bc4c00 }.insight-domain h3 { margin:0 0 18px;font:700 28px "Space Grotesk" }.insight-domain > div { display:grid;grid-template-columns:1fr 1fr;gap:8px }.insight-domain > div > span { padding:11px;color:#6e7781;border:1px solid #d8dee4;border-radius:8px;background:#f6f8fa;font-size:9px }.insight-domain > div strong { display:block;margin-top:5px;color:#24292f;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap }
.manager-digest-panel .panel-header { align-items: center; }
.manager-digest-text { margin-top: 14px; white-space: pre-wrap; line-height: 1.6; }
.security-events-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 14px; }
.metrics-trend-chart { display: flex; align-items: flex-end; gap: 4px; height: 90px; margin-top: 14px; padding-top: 10px; border-top: 1px solid var(--line); }
.metrics-trend-bar-wrap { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; height: 100%; gap: 4px; }
.metrics-trend-bar { width: 100%; max-width: 14px; background: linear-gradient(180deg, #0969da, #2da44e); border-radius: 3px 3px 0 0; min-height: 3px; }
.metrics-trend-bar-wrap small { font-size: 7px; color: var(--muted); }
.team-velocity-stats { display: flex; gap: 20px; margin: 10px 0 4px; }
.team-velocity-stats span { display: flex; flex-direction: column; gap: 3px; font-size: 9px; color: var(--muted); text-transform: uppercase; font-weight: 800; }
.team-velocity-stats strong { font-size: 16px; color: #24292f; text-transform: none; }
.slo-grid { display:grid;grid-template-columns:repeat(4,1fr);gap:10px }.slo-grid article { position:relative;overflow:hidden;padding:15px;border:1px solid #d8dee4;border-radius:9px;background:#f6f8fa }.slo-grid span,.slo-grid strong,.slo-grid small { display:block }.slo-grid span { color:#6e7781;font-size:8px;font-weight:900;text-transform:uppercase }.slo-grid strong { margin:7px 0;font:700 22px "Space Grotesk" }.slo-grid small { color:#8c959f;font-size:8px }.slo-grid i { position:absolute;left:0;bottom:0;width:var(--health);height:3px;background:linear-gradient(90deg,#0969da,#2da44e) }

.audit-stage { display:grid;grid-template-columns:minmax(0,1fr);gap:16px }.audit-stage .panel { margin:0 }
.audit-seal { position:relative;overflow:hidden;display:grid;grid-template-columns:auto 1fr auto;gap:22px;align-items:center;padding:24px;color:#f0f6fc;border:1px solid #30363d;border-radius:13px;background:linear-gradient(130deg,#0d1117,#161b22);box-shadow:0 18px 45px rgba(13,17,23,.16) }.audit-seal::after { content:"GW";position:absolute;right:18px;top:-30px;color:rgba(240,246,252,.05);font:800 130px "Space Grotesk";letter-spacing:-.1em;pointer-events:none }.audit-seal > * { position:relative;z-index:1 }.audit-seal .seal { width:74px;height:74px;display:grid;place-items:center;border-radius:50%;font-size:9px;font-weight:900;letter-spacing:.08em }.audit-seal .seal.valid { color:#7ee787;border:2px solid #3fb950;box-shadow:0 0 0 8px rgba(63,185,80,.08),inset 0 0 20px rgba(63,185,80,.1) }.audit-seal .seal.broken { color:#ff7b72;border:2px solid #f85149 }.audit-seal .eyebrow { color:#58a6ff }.audit-seal h2 { margin:0;font:700 30px "Space Grotesk" }.audit-seal p:last-child { margin:5px 0 0;color:#8b949e }.audit-seal > code { max-width:260px;overflow:hidden;color:#79c0ff;text-overflow:ellipsis }
.audit-stream { display:grid }.audit-stream article { display:grid;grid-template-columns:34px 1fr;gap:12px;position:relative;padding:17px 0;border-bottom:1px solid #d8dee4 }.audit-stream article:last-child { border:0 }.audit-glyph { position:relative }.audit-glyph::before { content:"";position:absolute;left:12px;top:-18px;bottom:-18px;border-left:2px solid #d0d7de }.audit-glyph i { position:relative;z-index:1;display:block;width:14px;height:14px;margin:4px 0 0 6px;border:3px solid white;border-radius:50%;background:#2da44e;box-shadow:0 0 0 2px #2da44e }.audit-failed .audit-glyph i { background:#cf222e;box-shadow:0 0 0 2px #cf222e }.audit-copy header { display:flex;align-items:center;gap:8px }.audit-copy header strong { font-size:12px }.audit-copy header span { padding:3px 5px;color:#0550ae;border-radius:4px;background:#ddf4ff;font-size:7px;font-weight:900 }.audit-copy time { margin-left:auto;color:#8c959f;font-size:9px }.audit-copy p { margin:6px 0;color:#57606a;font-size:10px;line-height:1.5 }.audit-copy footer { display:flex;flex-wrap:wrap;gap:8px;color:#8c959f;font-size:8px }.audit-copy footer code { color:#8250df }.audit-copy footer b { color:#0550ae }
@keyframes auditSealPulse { 0%,100% { box-shadow:0 0 0 8px rgba(63,185,80,.08),inset 0 0 20px rgba(63,185,80,.1) } 50% { box-shadow:0 0 0 12px rgba(63,185,80,.16),inset 0 0 26px rgba(63,185,80,.18) } }
.audit-seal .seal.valid { animation:auditSealPulse 2.6s ease-in-out infinite }
.audit-chain { display:grid;gap:4px }
.audit-day-group { display:grid;gap:2px }
.audit-day-separator { position:sticky;top:0;z-index:2;padding:8px 4px;color:#57606a;background:var(--card);font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.04em;border-bottom:1px solid #d8dee4 }
.audit-block { display:grid;grid-template-columns:38px 1fr;gap:10px;align-items:start;padding:4px 0 }
.audit-block-glyph { position:relative;display:grid;place-items:center;width:38px }
