.audit-block-glyph i { position:relative;z-index:1;display:grid;place-items:center;width:30px;height:30px;border-radius:9px;font-style:normal;font-size:13px;color:#fff;background:#57606a;box-shadow:0 3px 10px rgba(0,0,0,.12) }
.audit-block.family-commit .audit-block-glyph i { background:#0969da }
