.audit-hash-arrow { color:#8c959f;font-family:inherit }
.audit-hash-prev { padding:3px 7px;color:#57606a;border-radius:5px;background:#eaeef2 }
.audit-block-detail { margin-top:10px;padding-top:10px;border-top:1px dashed #d8dee4 }
.audit-block-detail p { margin:0 0 8px;color:#57606a;font-size:10px;line-height:1.5 }
