.control-grid { display:grid;grid-template-columns:repeat(4,1fr);gap:8px }.control-grid article { display:flex;align-items:center;gap:8px;padding:11px;border:1px solid #d8dee4;border-radius:8px;background:#f6f8fa }.control-grid i { padding:4px 5px;color:#116329;border-radius:4px;background:#dafbe1;font-size:7px;font-style:normal;font-weight:900 }.control-grid .disabled i { color:#a40e26;background:#ffebe9 }.control-grid strong { font-size:9px;text-transform:capitalize }.limit-strip { display:flex;flex-wrap:wrap;gap:7px;margin-top:14px }.limit-strip span { padding:6px 8px;color:#57606a;border:1px solid #d8dee4;border-radius:99px;font-size:9px }

