.native-component-layout { display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:12px;border:0!important;background:transparent!important }.native-components,.native-review { min-width:0;border:1px solid #cad7d0;border-radius:12px;background:white;overflow:hidden }.native-components > header { display:flex;justify-content:space-between;gap:15px;align-items:center;padding:18px 20px;border-bottom:1px solid #d5dfda }.native-components h3 { margin:4px 0;font:700 20px "Space Grotesk" }.native-components select { padding:8px;border:1px solid #cad7d0;border-radius:7px;font-size:7px }.native-component-table { max-height:590px;overflow:auto }.native-component-table > div,.native-component-table > button { display:grid;grid-template-columns:minmax(190px,1.35fr) .7fr .8fr .9fr .8fr;gap:9px;align-items:center;width:100%;padding:10px 13px;border:0;border-bottom:1px solid #dce5e0;background:white;text-align:left }.native-component-table > div { position:sticky;z-index:2;top:0;color:#7c8c84;background:#f3f6f4;font-size:6px;font-weight:900;text-transform:uppercase }.native-component-table > button:hover,.native-component-table > button.active { background:#f0faf5;box-shadow:inset 3px 0 #17a76d }.native-component-table span,.native-component-table em { overflow:hidden;font-size:7px;text-overflow:ellipsis }.native-component-table strong,.native-component-table small { display:block }.native-component-table strong { font-size:8px }.native-component-table small { margin-top:2px;color:#7b8a83;font-size:5px }.native-component-table button > span:nth-child(3) { display:grid;grid-template-columns:1fr auto;gap:6px;align-items:center }.native-component-table button > span:nth-child(3) i { height:4px;border-radius:4px;background:#22ad76 }.native-component-table em { padding:5px;border-radius:5px;color:#835d00;background:#fff3bf;font-style:normal;font-weight:900;text-align:center }.native-component-table em.review-confirmed,.native-component-table em.review-auto_confirmed { color:#076343;background:#d4f8e5 }.native-component-table em.review-rejected { color:#a40e26;background:#ffdadc }
