.role-tree-wrap { overflow-x: auto; padding: 16px 4px 8px; }
.role-tree, .role-tree ul { display: flex; list-style: none; margin: 0; padding-top: 24px; position: relative; }
.role-tree ul { padding-left: 0; }
.role-tree li { flex: none; display: flex; flex-direction: column; align-items: center; position: relative; padding: 24px 10px 0; }
.role-tree li::before, .role-tree li::after { content: ""; position: absolute; top: 0; right: 50%; width: 50%; height: 24px; border-top: 2px solid #d0d7de; }
.role-tree li::after { right: auto; left: 50%; border-left: 2px solid #d0d7de; }
.role-tree li:only-child::before, .role-tree li:only-child::after { display: none; }
.role-tree li:first-child::before { border: 0 none; }
.role-tree li:last-child::after { border: 0 none; }
.role-tree li:last-child::before { border-right: 2px solid #d0d7de; border-radius: 0 6px 0 0; }
.role-tree li:first-child::after { border-radius: 6px 0 0 0; }
.role-tree > li { padding-top: 0; }
.role-tree > li::before, .role-tree > li::after { display: none; }
.role-tree ul::before { content: ""; position: absolute; top: 0; left: 50%; border-left: 2px solid #d0d7de; width: 0; height: 24px; }
.role-tree-node { display: flex; flex-direction: column; align-items: center; gap: 3px; min-width: 120px; padding: 10px 14px; border: 1px solid #d0d7de; border-radius: 10px; background: #fff; box-shadow: 0 4px 14px rgba(31,35,40,.06); white-space: nowrap; }
.role-tree-node strong { font-size: 10px; }
.role-tree-node small { color: #6e7781; font-size: 8px; text-transform: uppercase; letter-spacing: .03em; }
.role-tree-root { color: #f0f6fc; border-color: #30363d; background: linear-gradient(140deg,#0d1117,#161b22); }
.role-tree-root small { color: #8b949e; }
.role-tree-scope { border-color: #54aeff; background: #ddf4ff; }
.role-tree-role { border-color: #7ee787; background: #dafbe1; }
.role-tree-user { flex-direction: row; align-items: center; gap: 8px; padding: 7px 10px 7px 8px; cursor: pointer; font: inherit; appearance: none; }
.role-tree-user .user-avatar { width: 24px; height: 24px; font-size: 8px; }
.role-tree-user strong { font-size: 9px; font-weight: 700; }
.role-tree-user:hover { border-color: #0969da; box-shadow: 0 4px 14px rgba(9,105,218,.1); }
.role-tree-status-dot { width: 7px; height: 7px; border-radius: 50%; margin-left: 2px; flex-shrink: 0; }
.role-tree-role-pill { text-transform: capitalize; }

.user-detail-dialog { width: min(560px, 100%); background: radial-gradient(circle at 100% 0, rgba(88,166,255,.18), transparent 42%), #0d1117; }
.user-detail-header { display: flex; align-items: center; gap: 14px; margin: 0 0 20px; padding-right: 64px; }
.user-detail-header .user-avatar { width: 46px; height: 46px; font-size: 14px; flex-shrink: 0; font-weight: 800; color: #fff; }
.user-detail-header > div { flex: 1; min-width: 0; }
.user-detail-header strong { display: block; overflow: hidden; font-size: 16px; color: #fff; text-overflow: ellipsis; white-space: nowrap; }
.user-detail-header small { display: block; overflow: hidden; margin-top: 2px; color: #8b949e; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
.role-tree-role-pill { flex-shrink: 0; padding: 5px 12px; font-size: 9.5px; font-weight: 800; letter-spacing: .03em; }
.role-tree-role-pill.role-tone-owner { color: #f0b72f; background: rgba(240,183,47,.14); border: 1px solid rgba(240,183,47,.35); }
.role-tree-role-pill.role-tone-editor { color: #58a6ff; background: rgba(88,166,255,.14); border: 1px solid rgba(88,166,255,.35); }
.role-tree-role-pill.role-tone-viewer { color: #8b949e; background: rgba(139,148,158,.14); border: 1px solid rgba(139,148,158,.35); }
.user-detail-kpis { grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 22px; }
.user-detail-kpis .team-roster-kpi { padding: 12px; border: 1px solid rgba(255,255,255,.06); border-radius: 10px; }
.user-detail-devices h4 { margin: 0 0 10px; color: #f0f6fc; font-size: 11px; text-transform: uppercase; letter-spacing: .04em; }
.user-detail-devices ul { display: grid; gap: 8px; list-style: none; margin: 0; padding: 0; }
.user-detail-devices li { display: flex; align-items: center; gap: 12px; padding: 11px 14px; border: 1px solid #30363d; border-radius: 10px; background: #161b22; }
.user-detail-devices li > div { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.user-detail-devices code { color: #f0f6fc; font-size: 11.5px; font-weight: 700; }
.user-detail-devices small { color: #8b949e; font-size: 9px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
