.user-detail-devices .pill.device-trust-unknown { color: #e3b341; background: rgba(212,167,44,.15); border: 1px solid rgba(212,167,44,.35); }
.user-detail-devices .pill.device-trust-blocked { color: #ff7b72; background: rgba(248,81,73,.15); border: 1px solid rgba(248,81,73,.35); }
.user-detail-devices .trace-button { flex-shrink: 0; padding: 6px 12px; border: 1px solid #30363d; border-radius: 7px; color: #f0f6fc; background: #21262d; font-size: 9.5px; font-weight: 800; }
.user-detail-devices .trace-button:hover { background: #2d333b; border-color: #58a6ff; color: #79c0ff; }
.user-detail-section { margin-bottom: 20px; }
.user-detail-section h4 { margin: 0 0 10px; color: #f0f6fc; font-size: 11px; text-transform: uppercase; letter-spacing: .04em; }
.user-detail-section p { margin: 0; color: #8b949e; font-size: 12px; }
.user-detail-sheet-list { display: grid; gap: 6px; list-style: none; margin: 0; padding: 0; }
.user-detail-sheet-list li { display: flex; align-items: center; justify-content: space-between; padding: 9px 12px; border: 1px solid #30363d; border-radius: 8px; background: #161b22; }
.user-detail-sheet-list strong { color: #f0f6fc; font-size: 11.5px; }
.user-detail-sheet-list small { color: #8b949e; font-size: 10px; }

/* Discovery Agent ("who should I ask") */
.discovery-ask-form { display: flex; gap: 8px; margin-bottom: 10px; }
.discovery-ask-form input { flex: 1; padding: 9px 12px; border: 1px solid var(--line); border-radius: 8px; font-size: 12px; }
.discovery-ask-form button { padding: 9px 16px; border: none; border-radius: 8px; background: #8250df; color: #fff; font-weight: 700; font-size: 11px; }
.discovery-ask-form button:disabled { opacity: .5; }
.discovery-result { margin-top: 10px; }
.discovery-top-pick { box-shadow: inset 0 0 0 1px #8250df; border-radius: 8px; }

/* RBAC Anomaly Agent */
.rbac-finding-row { display: grid; grid-template-columns: auto 1fr auto; gap: 12px; align-items: center; padding: 12px; border: 1px solid var(--line); border-radius: 8px; margin-bottom: 8px; background: #fff; }
.rbac-finding-body strong { display: block; font-size: 11px; text-transform: capitalize; }
.rbac-finding-body p { margin: 4px 0 0; font-size: 11px; color: var(--muted); }
.rbac-finding-actions { display: flex; flex-direction: column; gap: 6px; }
.rbac-finding-actions button { font-size: 9.5px; padding: 6px 10px; }

/* Team health digest */
.team-digest-panel .panel-header { align-items: center; }
.team-digest-body { display: flex; flex-direction: column; gap: 12px; margin-top: 10px; }
.ai-narrative { margin: 0; padding: 12px 14px; border-radius: 10px; background: rgba(9,105,218,.06); border: 1px solid rgba(9,105,218,.18); font-size: 13px; line-height: 1.5; }
.team-digest-observations { display: grid; gap: 6px; margin: 0; padding-left: 18px; font-size: 12.5px; color: var(--ink); }
.user-detail-actions { margin-top: 22px; padding-top: 16px; border-top: 1px solid #30363d; text-align: right; }
.user-detail-actions .trace-button.danger { padding: 8px 14px; border: 1px solid rgba(248,81,73,.4); border-radius: 8px; color: #ff7b72; background: rgba(248,81,73,.1); font-size: 10.5px; font-weight: 800; }
.user-detail-actions .trace-button.danger:hover { background: rgba(248,81,73,.18); }
.trace-button.danger { color: #cf222e; border-color: #cf222e; background: #ffebe9; }
.role-tree-onboard { display: flex; gap: 8px; align-items: center; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--line); flex-wrap: wrap; }
.role-tree-onboard input, .role-tree-onboard select { padding: 6px 9px; border: 1px solid var(--line); border-radius: 6px; font-size: 11px; }
.role-tree-onboard button { padding: 7px 14px; border: 0; border-radius: 6px; background: #0969da; color: #fff; font-size: 11px; font-weight: 800; cursor: pointer; }
.role-tree-onboard button:disabled { opacity: .5; cursor: not-allowed; }
.role-tree-filter { display: flex; margin: 14px 0 4px; }
.role-tree-filter label { display: flex; flex-direction: column; gap: 4px; color: var(--muted); font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .03em; }
.role-tree-filter select { padding: 8px 10px; border: 1px solid var(--line); border-radius: 7px; font-size: 11px; text-transform: none; letter-spacing: 0; }
/* Family tree: a shared rail per level plus one stem per child — a plain
   CSS org-chart technique that stays genuinely connected at any width and
   only needs horizontal scroll at the level that actually has many
   siblings, instead of one ever-widening single-row ribbon. */
.fam-tree { display: flex; flex-direction: column; align-items: center; min-width: max-content; padding: 8px 12px 20px; }
.fam-tree-root { padding: 12px 20px; border: 1px solid #30363d; border-radius: 10px; color: #f0f6fc; background: linear-gradient(140deg,#0d1117,#161b22); text-align: center; box-shadow: 0 8px 22px rgba(13,17,23,.12); }
.fam-tree-root strong { display: block; font-size: 13px; }
.fam-tree-root small { display: block; margin-top: 3px; color: #8b949e; font-size: 9px; text-transform: uppercase; letter-spacing: .03em; }
.fam-tree-level { display: flex; gap: 22px; margin-top: 20px; padding-top: 20px; border-top: 2px solid #d0d7de; }
.fam-tree-branch { position: relative; display: flex; flex-direction: column; align-items: center; }
.fam-tree-branch::before { content: ""; position: absolute; top: -20px; left: 50%; width: 2px; height: 20px; background: #d0d7de; transform: translateX(-50%); }
.fam-tree-node { min-width: 0; white-space: nowrap; }
.fam-tree-scope { padding: 10px 14px; border: 1px solid #54aeff; border-radius: 9px; background: #ddf4ff; text-align: center; }
.fam-tree-scope strong { display: block; font-size: 12px; }
.fam-tree-scope small { display: block; margin-top: 2px; color: #0550ae; font-size: 8px; text-transform: uppercase; letter-spacing: .03em; }
.fam-tree-role { padding: 6px 12px; border: 1px solid #7ee787; border-radius: 99px; background: #dafbe1; color: #116329; font-size: 9px; font-weight: 900; text-transform: uppercase; letter-spacing: .03em; }
.fam-tree-user { display: flex; align-items: center; gap: 7px; padding: 6px 8px 6px 6px; border: 1px solid var(--line); border-radius: 99px; background: #fff; box-shadow: 0 2px 8px rgba(31,35,40,.05); }
.fam-tree-user .user-avatar { width: 22px; height: 22px; font-size: 8px; }
.fam-tree-user span { font-size: 10px; font-weight: 600; }
.fam-tree-user button { padding: 0; width: 15px; height: 15px; border: 0; border-radius: 50%; color: #cf222e; background: #ffebe9; font-size: 10px; line-height: 1; }
.fam-tree-level-roles, .fam-tree-level-users { gap: 14px; }
@media (max-width:1200px) { .security-admin-grid { grid-template-columns:1fr }.role-view-panel,.service-panel { grid-column:auto }.security-stat-grid { grid-template-columns:1fr 1fr } }
@media (max-width:760px) { .security-admin-hero { grid-template-columns:1fr;padding:26px }.security-shield { width:120px }.security-stat-grid { grid-template-columns:1fr 1fr }.security-role-form,.policy-composer { grid-template-columns:1fr }.identity-list article { grid-template-columns:36px 1fr auto }.identity-list article button { grid-column:2;justify-self:start }.issued-secret { grid-template-columns:1fr }.security-admin-panel { padding:16px } }

