.ai-copilot-layout { display:grid;grid-template-columns:minmax(0,1.45fr) minmax(320px,.7fr);gap:14px;align-items:stretch }.ai-state { padding:6px 9px;border-radius:99px;color:#8a6510;background:#fff1bd;font-size:8px;font-weight:900 }.ai-state.connected { color:#075d3e;background:#cff5e3 }.ai-provider-status { display:flex;align-items:center;gap:7px }.ai-provider-status > button { padding:6px 9px;color:#075d3e;border:1px solid #9bd8bf;border-radius:99px;background:#effbf5;font-size:8px;font-weight:900 }.ai-prompt-deck { display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:18px 22px 0 }.ai-prompt-deck button { min-width:0;padding:13px;border:1px solid #d6e1dc;border-radius:10px;background:#f5f9f7;text-align:left }.ai-prompt-deck span,.ai-prompt-deck small { display:block }.ai-prompt-deck span { color:#0d6648;font-size:9px;font-weight:900 }.ai-prompt-deck small { overflow:hidden;margin-top:6px;color:#66786f;font-size:8px;line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical }.ai-conversation > textarea { width:calc(100% - 44px);min-height:150px;margin:14px 22px 0;padding:16px;border:1px solid #bacbc3;border-radius:11px;color:#dff8ec;background:#101b17;font:500 11px/1.65 ui-monospace,Consolas,monospace;resize:vertical }.ai-conversation > footer { display:grid;grid-template-columns:minmax(180px,.55fr) minmax(170px,.35fr);justify-content:end;gap:8px;padding:13px 22px 22px }.ai-conversation select,.ai-conversation footer button { min-width:0;padding:11px;border-radius:8px;font-size:10px;font-weight:900 }.ai-conversation footer button,.ai-run,.ai-controls-room > header button,.ai-evaluations > header button,.ai-admin-policy > header button { color:#062d1f;border:1px solid #51cb9b;background:var(--ai-mint) }.ai-provider-inline { display:grid;grid-template-columns:minmax(180px,.85fr) minmax(190px,1fr) minmax(190px,1fr) auto;gap:10px;align-items:end;margin:0 22px 22px;padding:15px;border:1px dashed #8fbaa8;border-radius:10px;background:linear-gradient(120deg,#eefaf5,#f9fbfa) }.ai-provider-inline > div:first-child { align-self:center }.ai-provider-inline strong,.ai-provider-inline small,.ai-provider-inline label > span { display:block }.ai-provider-inline label { display:grid;gap:5px;margin:0;color:#486158;font-size:8px;font-weight:900 }.ai-provider-inline small { margin-top:4px;color:#687a72;font-size:8px }.ai-provider-inline input,.ai-provider-inline select,.ai-provider-inline button { min-width:0;margin:0;padding:10px;border-radius:7px;font-size:9px }.ai-provider-inline button { color:#fff;border:0;background:#168457;font-weight:900 }.ai-provider-actions { display:flex;gap:6px }.ai-provider-actions .secondary { color:#486158;border:1px solid #c2d2cb;background:#fff }.ai-provider-inline .ai-free-notice { grid-column:1/-1;margin:0;padding:9px 11px;color:#765900;border:1px solid #e4cf81;border-radius:7px;background:#fff8d9;line-height:1.5 }
.ai-answer { color:#dcece5;background:#0d1713 }.ai-answer > header { border-color:#253931 }.ai-answer > header > span { display:grid;width:52px;height:52px;place-items:center;border-radius:50%;color:#73efbd;background:conic-gradient(#65e3b4 var(--confidence),#263a32 0);font:800 12px "Space Grotesk";box-shadow:inset 0 0 0 7px #0d1713 }.ai-answer > h3,.ai-answer > p,.ai-answer > .ai-evidence-list,.ai-answer > .ai-warning { margin-left:22px;margin-right:22px }.ai-answer-runtime { display:grid;grid-template-columns:1.5fr .8fr .8fr;margin:16px 22px 0;overflow:hidden;border:1px solid #2d443a;border-radius:9px;background:#101e18 }.ai-answer-runtime span { min-width:0;padding:10px;color:#719186;border-right:1px solid #2d443a;font-size:7px;font-weight:900 }.ai-answer-runtime span:last-child { border-right:0 }.ai-answer-runtime strong { display:block;overflow:hidden;margin-top:4px;color:#65e3b4;font-size:8px;text-overflow:ellipsis;text-transform:uppercase;white-space:nowrap }.ai-answer > h3 { margin-top:22px;font-size:22px }.ai-answer > p { color:#a4bbb1;font-size:11px;line-height:1.7 }.ai-evidence-list { display:grid;gap:7px;margin-top:20px;margin-bottom:18px;max-height:330px;overflow:auto }.ai-evidence-list article { display:grid;grid-template-columns:85px minmax(0,1fr);gap:4px 10px;padding:11px;border:1px solid #2d443a;border-radius:8px;background:#121f1a }.ai-evidence-list span { color:#65e3b4;font-size:7px;font-weight:900 }.ai-evidence-list strong { font-size:9px }.ai-evidence-list code { grid-column:2;color:#739186;font-size:7px }.ai-warning { display:block;margin-bottom:8px;padding:9px;color:#f4d687;border:1px solid #635529;border-radius:7px;background:#2b2717;font-size:8px }.ai-empty { display:grid;min-height:220px;place-content:center;padding:30px;color:#6d7e76;text-align:center }.ai-empty strong { color:inherit;font:700 20px "Space Grotesk" }.ai-empty p { max-width:450px;line-height:1.6 }.ai-answer .ai-empty { color:#829b90 }.ai-answer .ai-empty strong { color:#dff6ec }
.ai-controls-room > header button,.ai-evaluations > header button,.ai-admin-policy > header button { padding:10px 13px;border-radius:8px;font-size:9px;font-weight:900 }.ai-control-list { display:grid;gap:8px;padding:18px }.ai-control-list article { display:grid;grid-template-columns:75px minmax(0,1fr) auto;gap:14px;align-items:center;padding:15px;border:1px solid #dae3df;border-radius:10px;background:#f8faf9 }.ai-control-list article > span { width:max-content;padding:5px 7px;border-radius:99px;color:#865f00;background:#fff0b5;font-size:8px;font-weight:900 }.ai-control-list article.severity-critical > span,.ai-control-list article.severity-high > span { color:#9d1529;background:#ffe1e5 }.ai-control-list strong { font-size:11px }.ai-control-list p { margin:5px 0;color:#687a72;font-size:9px }.ai-control-list code { color:#2172b5;font-size:7px }.ai-control-list b { color:#71837b;font-size:7px;text-transform:uppercase }
.ai-agent-layout { display:grid;grid-template-columns:minmax(0,1.15fr) minmax(330px,.65fr);gap:14px;align-items:start }.ai-agent-launcher { padding:24px }.ai-agent-launcher > h3 { margin:0 0 18px }.ai-agent-cards { display:grid;grid-template-columns:repeat(3,1fr);gap:8px }.ai-agent-cards button { min-width:0;min-height:145px;padding:15px;border:1px solid #d5e0db;border-radius:11px;background:#f7faf8;text-align:left }.ai-agent-cards button.active { border-color:#4bc492;background:linear-gradient(145deg,#e3fff3,#fff);box-shadow:inset 0 0 0 1px #65e3b4 }.ai-agent-cards span,.ai-agent-cards strong,.ai-agent-cards small { display:block }.ai-agent-cards span { color:#087b55;font-size:8px;font-weight:900 }.ai-agent-cards strong { margin:8px 0;font-size:11px }.ai-agent-cards small { color:#6d7e76;font-size:8px;line-height:1.5 }.ai-agent-launcher > textarea { width:100%;min-height:115px;margin:13px 0;padding:13px;border-radius:9px;font:500 10px/1.55 ui-monospace,Consolas,monospace;resize:vertical }.ai-run { width:100%;padding:12px;border-radius:8px;font-size:10px;font-weight:900 }.ai-policy-note { display:block;margin-top:12px;color:#6b7c74;font-size:8px;line-height:1.6 }.ai-run-ledger-toggle > span { padding:5px 8px;border-radius:99px;color:#0d6548;background:#dcf7eb;font-size:8px;font-weight:900 }.ai-run-ledger > article { display:flex;align-items:center;justify-content:space-between;gap:13px;padding:15px 18px;border-top:1px solid #dde5e1 }.ai-run-ledger > article:first-of-type { border-top:0 }.ai-run-ledger article span,.ai-run-ledger article strong,.ai-run-ledger article code { display:block }.ai-run-ledger article span { color:#0d7753;font-size:7px;font-weight:900 }.ai-run-ledger article strong { margin:5px 0;font-size:10px }.ai-run-ledger article code { color:#71847b;font-size:7px }.ai-run-ledger article button { padding:9px;color:#fff;border:0;border-radius:7px;background:#b3263a;font-size:8px;font-weight:900 }
.ai-run-ledger-toggle { display:flex; align-items:center; gap:12px; width:100%; padding:22px 24px; border:0; border-bottom:1px solid #dde6e1; background:transparent; cursor:pointer; text-align:left; font:inherit; }
.ai-run-ledger.collapsed .ai-run-ledger-toggle { border-bottom:0; }
.ai-run-ledger-toggle .eyebrow { flex:1; margin:0; }
.ai-collapse-caret { width:8px; height:8px; margin-left:4px; border-right:2px solid #0d6548; border-bottom:2px solid #0d6548; transform:rotate(45deg); transition:transform .15s ease; flex-shrink:0; }
.ai-collapse-caret.open { transform:rotate(225deg); }

/* Control insight "Explain" wiring */
.ai-insight-actions { display:flex; flex-direction:column; align-items:flex-end; gap:8px; }
.ai-insight-actions button { padding:7px 10px; border:1px solid #9bd8bf; border-radius:8px; color:#075d3e; background:#effbf5; font-size:8px; font-weight:900; white-space:nowrap; }
.ai-insight-actions button:disabled { opacity:.6; }
.ai-insight-explanation { margin-top:8px; padding:10px 12px; border:1px dashed #9bd8bf; border-radius:8px; background:#f3fbf7; color:#3c2a63; font-size:9.5px; line-height:1.6; }

/* Signal Registry */
.signal-registry-header { display:flex; align-items:flex-start; justify-content:space-between; gap:18px; padding:22px 24px; border-bottom:1px solid #dde6e1; }
.signal-registry-header .muted { max-width:640px; margin-top:6px; color:#6d7e76; font-size:9px; line-height:1.6; }
.signal-registry-actions { display:flex; gap:8px; flex-shrink:0; }
.signal-registry-actions button { padding:10px 14px; border-radius:8px; font-size:9px; font-weight:900; white-space:nowrap; }
.signal-registry-actions button:first-child { color:#075d3e; border:1px solid #9bd8bf; background:#effbf5; }
.signal-add-button { color:#062d1f !important; border:0 !important; background:var(--ai-mint) !important; }
.signal-registry-group { padding:18px 24px; border-top:1px solid #eef2f0; }
.signal-registry-group h4 { margin:0 0 12px; font:700 12px "Space Grotesk"; }
.signal-loading { padding:30px 24px; }
.signal-grid { display:grid; grid-template-columns:repeat(auto-fill, minmax(260px, 1fr)); gap:12px; }
.signal-card { display:flex; flex-direction:column; gap:8px; padding:15px; border:1px solid #dae3df; border-radius:11px; background:#f8faf9; }
.signal-card-disabled { opacity:.55; }
.signal-card > header { display:flex; align-items:center; justify-content:space-between; gap:8px; }
.signal-card strong { font-size:11px; }
.signal-card p { margin:0; color:#5b6d64; font-size:9px; line-height:1.55; }
.signal-severity-badge { padding:4px 8px; border-radius:99px; font-size:7px; font-weight:900; letter-spacing:.03em; }
.signal-severity-badge.severity-high { color:#9d1529; background:#ffe1e5; }
.signal-severity-badge.severity-medium { color:#865f00; background:#fff0b5; }
.signal-severity-badge.severity-low { color:#0d6548; background:#dcf7eb; }
.signal-origin-badge { padding:4px 8px; border-radius:99px; font-size:7px; font-weight:900; text-transform:uppercase; }
.signal-origin-badge.builtin { color:#3c2a63; background:#ece3ff; }
.signal-origin-badge.custom { color:#075d3e; background:#dcf7eb; }
.signal-condition-summary { display:block; padding:6px 8px; border-radius:6px; background:#eef2f0; color:#405048; font-size:8px; word-break:break-word; }
.signal-card-stats { display:flex; flex-wrap:wrap; gap:10px; color:#71847b; font-size:7.5px; font-weight:700; text-transform:uppercase; }
.signal-card > footer { display:flex; align-items:center; justify-content:space-between; gap:8px; margin-top:auto; padding-top:8px; border-top:1px solid #e5ebe8; }
.signal-toggle { display:flex; align-items:center; gap:6px; font-size:8px; font-weight:800; color:#3c4a44; }
.signal-card footer button { padding:6px 9px; border:1px solid #d5e0db; border-radius:7px; background:#fff; font-size:8px; font-weight:800; }
.signal-delete { color:#b3263a !important; border-color:#f3c6cc !important; }

/* Signal modals (reuse .checkout-backdrop/.checkout-dialog) */
.signal-form-dialog, .signal-history-dialog { color:#1f2a26; background:#fff; }
.signal-form-dialog h2, .signal-history-dialog h2 { color:#1f2a26; font-size:24px; }
.signal-form-dialog .muted, .signal-history-dialog .muted { color:#6d7e76; }
.signal-form-field { display:grid; gap:6px; margin:14px 0; font-size:9px; font-weight:800; color:#3c4a44; }
.signal-form-field input, .signal-form-field select, .signal-form-field textarea { padding:10px; border:1px solid #cfd9d4; border-radius:8px; font:500 10px/1.5 inherit; }
.signal-form-field small { font-weight:500; color:#6d7e76; }
.signal-enum-fieldset { display:flex; flex-wrap:wrap; gap:8px; margin:14px 0; padding:12px; border:1px solid #dae3df; border-radius:9px; }
.signal-enum-fieldset legend { padding:0 6px; font-size:9px; font-weight:800; color:#3c4a44; }
.signal-enum-option { display:flex; align-items:center; gap:6px; padding:6px 10px; border:1px solid #d5e0db; border-radius:99px; font-size:8.5px; }
.signal-form-footer { display:flex; justify-content:flex-end; margin-top:16px; }
.signal-form-footer button { padding:11px 18px; border:0; border-radius:8px; color:#062d1f; background:var(--ai-mint); font-size:10px; font-weight:900; }
.signal-run-history { display:grid; gap:8px; margin:16px 0 0; padding:0; list-style:none; }
.signal-run-history li { display:flex; align-items:center; gap:12px; padding:10px 12px; border:1px solid #e5ebe8; border-radius:8px; font-size:9px; flex-wrap:wrap; }
.signal-run-failed { border-color:#f3c6cc; background:#fff5f6; }
.signal-run-status-badge { padding:3px 7px; border-radius:99px; font-size:7px; font-weight:900; background:#eef2f0; }
.signal-run-status-badge.failed { color:#b3263a; background:#ffe1e5; }
.signal-run-status-badge.completed { color:#0d6548; background:#dcf7eb; }
.signal-run-error { flex-basis:100%; color:#b3263a; }

/* Agent Store -- a Play-Store-style catalogue replacing the old bare
   3-agent launcher + read-only roster list. */
.ai-agent-store-layout { display: flex; flex-direction: column; gap: 14px; }
.agent-store { padding: 26px; }
.agent-store-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 22px; }
.agent-store-header h3 { margin: 4px 0 6px; font-size: 20px; }
.agent-store-category { margin-bottom: 22px; }
.agent-store-category:last-child { margin-bottom: 0; }
.agent-store-category h4 { margin: 0 0 10px; font-size: 10px; font-weight: 900; letter-spacing: .04em; text-transform: uppercase; color: #6d7e76; }
.agent-store-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 12px; }
.agent-store-card { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 4px; min-height: 160px; padding: 18px; border: 1px solid #e2e8e5; border-radius: 14px; background: #fff; text-align: left; cursor: pointer; transition: transform .12s ease, box-shadow .12s ease, border-color .12s ease; }
.agent-store-card:hover { transform: translateY(-2px); border-color: #c7d6cf; box-shadow: 0 10px 26px rgba(15, 40, 30, .1); }
.agent-store-card strong { margin-top: 10px; font-size: 12.5px; color: #0d1c15; }
.agent-store-card small { color: #667a71; font-size: 10px; line-height: 1.5; }
.agent-store-level { position: absolute; top: 14px; right: 14px; padding: 3px 7px; border-radius: 99px; background: #f0f4f2; color: #55655e; font-size: 7px; font-weight: 900; }
.agent-store-logo { display: grid; place-items: center; flex-shrink: 0; border-radius: 12px; color: #fff; font-weight: 800; box-shadow: 0 6px 16px rgba(0,0,0,.18); }

.agent-store-modal { width: min(640px, 100%); max-height: 88vh; overflow-y: auto; background: #fff; color: #0d1c15; }
.agent-store-modal-header { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 18px; padding-right: 40px; }
.agent-store-modal-header .pill { display: inline-block; margin-bottom: 6px; padding: 3px 9px; border-radius: 99px; background: #eef4f1; color: #3a4a42; font-size: 8px; font-weight: 900; text-transform: uppercase; letter-spacing: .03em; }
.agent-store-modal-header h3 { margin: 0 0 6px; font-size: 16px; text-transform: capitalize; }
.agent-store-modal-header p { margin: 0; color: #5c6d64; font-size: 11px; line-height: 1.55; }
.agent-store-inputs { display: flex; flex-direction: column; gap: 12px; }
.agent-store-inputs label { display: flex; flex-direction: column; gap: 6px; font-size: 9.5px; font-weight: 800; color: #45544c; text-transform: uppercase; letter-spacing: .03em; }
.agent-store-optional-note { margin: -4px 0 2px; font-size: 10.5px; font-style: italic; }
.agent-store-inputs input, .agent-store-inputs select, .agent-store-inputs textarea { padding: 10px 12px; border: 1px solid #d5e0db; border-radius: 8px; font-size: 12px; font-weight: 400; text-transform: none; letter-spacing: normal; color: #0d1c15; font-family: inherit; }
.agent-store-inputs textarea { min-height: 80px; resize: vertical; font-family: ui-monospace, Consolas, monospace; }
.agent-store-toggle { display: flex; gap: 8px; }
.agent-store-toggle button { flex: 1; padding: 9px; border: 1px solid #d5e0db; border-radius: 8px; background: #f7faf8; font-size: 10px; font-weight: 800; }
.agent-store-toggle button.active { border-color: #4bc492; background: linear-gradient(145deg,#e3fff3,#fff); color: #0d6548; }
.agent-store-inputs .ai-run { margin-top: 4px; }
.agent-store-result { margin-top: 16px; padding-top: 14px; border-top: 1px solid #e2e8e5; font-size: 12px; line-height: 1.6; color: #263b30; }
.agent-store-result ol, .agent-store-result ul { margin: 8px 0 0; padding-left: 18px; }
.agent-store-result li { margin-bottom: 6px; }
.agent-store-note { margin-top: 10px; padding: 10px 12px; border-radius: 8px; background: #fff8e6; color: #7a5b00; font-size: 11px; }
.agent-store-candidate { padding: 10px 12px; margin-bottom: 6px; border: 1px solid #e2e8e5; border-radius: 8px; }
.agent-store-candidate.top { border-color: #4bc492; background: linear-gradient(145deg,#e3fff3,#fff); }
.agent-store-candidate strong { display: block; font-size: 11.5px; text-transform: capitalize; }
.agent-store-candidate small { color: #667a71; font-size: 10px; }

/* Answer bubbles -- the collapsible, bulleted, cross-referenced result
   presentation shared by every agent's output, replacing plain paragraphs
   (and, critically, ever showing a raw JSON blob) with a scannable card. */
.agent-answer-bubble { margin-bottom: 10px; border: 1px solid #e2e8e5; border-radius: 12px; background: #fbfcfb; overflow: hidden; }
.agent-answer-bubble:last-child { margin-bottom: 0; }
.agent-answer-bubble-header { display: flex; align-items: center; gap: 10px; width: 100%; padding: 12px 14px; text-align: left; background: #fff; }
.agent-answer-bubble-header strong { flex: 1; font-size: 12px; color: #0d1c15; text-transform: capitalize; }
.agent-answer-bubble-toggle { font-size: 8px; font-weight: 800; color: #8250df; text-transform: uppercase; letter-spacing: .03em; }
.agent-answer-bubble-body { padding: 4px 16px 14px; }
.agent-answer-badge { flex-shrink: 0; padding: 3px 9px; border-radius: 99px; font-size: 8px; font-weight: 900; text-transform: uppercase; letter-spacing: .03em; }
.agent-answer-badge.tone-neutral { background: #eef4f1; color: #3a4a42; }
.agent-answer-badge.tone-low { background: #dafbe1; color: #116329; }
.agent-answer-badge.tone-medium { background: #fff8c5; color: #7d4e00; }
.agent-answer-badge.tone-high { background: #ffebe9; color: #a40e26; }
.agent-answer-bullets { margin: 8px 0 0; padding-left: 18px; font-size: 12px; line-height: 1.65; color: #263b30; }
.agent-answer-bullets li { margin-bottom: 7px; }
.agent-answer-bullets.numbered li { display: flex; flex-direction: column; gap: 2px; margin-bottom: 12px; }
.agent-answer-bullets.numbered li > b { color: #3c2a63; }
.agent-answer-bullets.numbered li > span { color: #263b30; }
.agent-answer-references { margin-top: 12px; padding-top: 12px; border-top: 1px dashed #d5e0db; }
.agent-answer-references h5 { margin: 0 0 8px; font-size: 8.5px; font-weight: 900; text-transform: uppercase; letter-spacing: .03em; color: #6d7e76; }
.agent-answer-reference { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px; padding: 7px 10px; margin-bottom: 5px; border-radius: 7px; background: #fff; border: 1px solid #eaefec; font-size: 10.5px; }
.agent-answer-reference:last-child { margin-bottom: 0; }
.agent-answer-reference-label { font-weight: 800; color: #0969da; font-family: ui-monospace, Consolas, monospace; }
.agent-answer-reference-detail { color: #667a71; }

/* Step flow -- a connected pipeline diagram for sequential AI output
