/* Local EUC Storage and Post-Merge Notifications */
.notice-banner { background: #dafbe1; color: #116329; border: 1px solid #4ac26b; padding: 12px 14px; border-radius: 10px; margin: 12px 0; }
.notice-banner.global { display: flex; justify-content: space-between; align-items: center; margin: 0 0 16px; box-shadow: 0 4px 12px rgba(17,99,41,.08); }
.notice-banner button { border: 0; background: none; color: inherit; font-weight: 800; cursor: pointer; }

.euc-storage-settings { margin-top: 16px; }
.euc-storage-form { display: grid; gap: 14px; margin-top: 18px; }
.euc-storage-form label { margin: 0; display: grid; gap: 6px; }
.euc-storage-form input { width: 100%; max-width: 600px; font-family: ui-monospace, SFMono-Regular, Consolas, monospace; }
.euc-storage-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-top: 8px; }
.euc-storage-actions .primary-button { width: auto; }
.euc-storage-actions .secondary-button { width: auto; }
.settings-feedback { font-size: 13px; font-weight: 600; color: var(--green); }
.settings-feedback.error { color: var(--red); }
.form-error-inline { color: var(--red); font-size: 13px; margin: 6px 0 0; font-weight: 600; }
.folder-modal-dialog { max-width: 540px; }
.folder-modal-dialog label { margin: 14px 0 8px; }
.folder-modal-dialog input { width: 100%; font-family: ui-monospace, SFMono-Regular, Consolas, monospace; }
.modal-actions-strip { display: flex; justify-content: flex-end; gap: 12px; margin-top: 20px; }
.modal-actions-strip button { width: auto; }

/* Screen and tab transitions: smooth fade-out and fade-in */
.workspace-screen-container,
.topbar-heading {
  will-change: opacity, transform;
}

.workspace-screen-container.fade-out,
.topbar-heading.fade-out {
  opacity: 0;
  transform: translateY(-4px);
  transition: opacity 140ms cubic-bezier(0.4, 0, 1, 1), transform 140ms cubic-bezier(0.4, 0, 1, 1);
  pointer-events: none;
}

.workspace-screen-container.fade-in,
.topbar-heading.fade-in {
  animation: screenFadeIn 220ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes screenFadeIn {
  0% {
    opacity: 0;
    transform: translateY(6px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Sub-views and tabs smooth fade-in */
.euc-sheet-tree,
.euc-patterns,
.euc-object-grid,
.euc-dependencies,
.sheet-tabs,
.data-table {
  animation: screenFadeIn 200ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

/* Refresh icon button */
.refresh-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 12px;
  min-width: 42px;
  min-height: 42px;
  cursor: pointer;
}

.refresh-button .refresh-icon {
  display: block;
  transition: transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.refresh-button:hover:not(:disabled) .refresh-icon {
  transform: rotate(60deg);
}

.refresh-button.is-refreshing .refresh-icon,
.refresh-icon.spinning {
  animation: refreshSpin 0.75s linear infinite;
}

@keyframes refreshSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

